package com.acme.functions;

import javax.ws.rs.POST;
import javax.ws.rs.Path;
import javax.ws.rs.Consumes;
import javax.ws.rs.Produces;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import java.util.Formatter;
import java.util.logging.Logger;
import java.util.logging.Level;
import org.eclipse.microprofile.config.inject.ConfigProperty;
import javax.inject.Inject;
import javax.enterprise.context.ApplicationScoped;

@Path("/api/v1/audit")
@ApplicationScoped
public class AuditEventHandler {

    private static final Logger LOGGER = Logger.getLogger(AuditEventHandler.class.getName());

    @Inject
    @ConfigProperty(name = "audit.template.prefix", defaultValue = "[AUDIT] ")
    String templatePrefix;

    @Inject
    @ConfigProperty(name = "audit.db.connection", defaultValue = "jdbc:postgresql://internal-db:5432/audit")
    String dbConnection;

    @Inject
    @ConfigProperty(name = "secrets.api.key")
    String internalApiKey;

    @POST
    @Path("/log")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response logAuditEvent(AuditRequest request) {
        try {
            // Validate basic structure
            if (request == null || request.getMessage() == null) {
                return Response.status(400).entity("{\"error\":\"missing message\"}").build();
            }

            // Build formatted audit string using user-controlled format template
            String userTemplate = request.getFormatTemplate();
            if (userTemplate == null) {
                userTemplate = "%s";
            }

            // Format the audit message - user controls the format string
            StringBuilder sb = new StringBuilder();
            Formatter formatter = new Formatter(sb);
            String fullTemplate = templatePrefix + userTemplate;

            // VULNERABILITY: User-controlled format string with internal secrets on stack
            // The formatter arguments include sensitive data that can be leaked
            // via positional format specifiers like %2$s, %3$s
            formatter.format(
                fullTemplate,
                request.getMessage(),
                dbConnection,
                internalApiKey,
                System.getenv("AWS_SECRET_ACCESS_KEY"),
                System.getenv("AWS_SESSION_TOKEN")
            );
            formatter.close();

            String formattedMessage = sb.toString();
            LOGGER.log(Level.INFO, "Audit event processed: {0}", formattedMessage);

            // Return the formatted message in response (information disclosure)
            AuditResponse resp = new AuditResponse();
            resp.setStatus("recorded");
            resp.setFormattedEntry(formattedMessage);
            resp.setTimestamp(System.currentTimeMillis());

            return Response.ok(resp).build();

        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error processing audit event", e);
            return Response.status(500)
                .entity("{\"error\":\"internal processing error\"}").build();
        }
    }

    @POST
    @Path("/batch")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response batchProcess(BatchAuditRequest batch) {
        if (batch == null || batch.getEvents() == null) {
            return Response.status(400).build();
        }
        int processed = 0;
        for (AuditRequest req : batch.getEvents()) {
            logAuditEvent(req);
            processed++;
        }
        return Response.ok("{\"processed\":" + processed + "}").build();
    }

    public static class AuditRequest {
        private String message;
        private String formatTemplate;
        public String getMessage() { return message; }
        public void setMessage(String message) { this.message = message; }
        public String getFormatTemplate() { return formatTemplate; }
        public void setFormatTemplate(String formatTemplate) { this.formatTemplate = formatTemplate; }
    }

    public static class BatchAuditRequest {
        private java.util.List<AuditRequest> events;
        public java.util.List<AuditRequest> getEvents() { return events; }
        public void setEvents(java.util.List<AuditRequest> events) { this.events = events; }
    }

    public static class AuditResponse {
        private String status;
        private String formattedEntry;
        private long timestamp;
        public String getStatus() { return status; }
        public void setStatus(String status) { this.status = status; }
        public String getFormattedEntry() { return formattedEntry; }
        public void setFormattedEntry(String formattedEntry) { this.formattedEntry = formattedEntry; }
        public long getTimestamp() { return timestamp; }
        public void setTimestamp(long timestamp) { this.timestamp = timestamp; }
    }
}
